mapper.select:
SELECT sou_project.PROJECT_ID, sou_project.PROCESS_CONFIG_ID, sou_project.SOU_NO, sou_project.SOU_NAME, sou_project.CURRENT_ROUND, sou_project.PUBLISH_SCOPE, sou_project.PROJECT_STATUS, sou_project.SIGN_UP_END_TIME, sou_project.ORDER_START_TIME, sou_project.ORDER_END_TIME, sou_project.PUBLISH_TIME, sou_project.ALLOW_WITHDRAW, sou_project.CREATED_BY, sou_project.ext_Project_No, sou_order.ORDER_STATUS, vendor.JOIN_ROUND, case when vendor.SIGN_UP_STATUS is null then 'NO_SIGN_UP' else vendor.SIGN_UP_STATUS end sign_up_status FROM scc_sou_project sou_project JOIN scc_sou_vendor vendor on vendor.PROJECT_ID = sou_project.PROJECT_ID and vendor.VENDOR_ID = #{queryParam.vendorId} LEFT JOIN scc_sou_order sou_order ON sou_project.PROJECT_ID = sou_order.PROJECT_ID AND sou_order.VENDOR_ID = #{queryParam.vendorId}
WHERE sou_project.PROJECT_STATUS NOT IN ('DRAFT')
and sou_project.SOU_TYPE = #{souType}
AND sou_project.SOU_NO LIKE concat('%', concat(#{queryParam.souNo}, '%'))
AND sou_project.SOU_NAME LIKE concat('%', concat(#{queryParam.souName}, '%'))
AND sou_project.PROJECT_STATUS = #{queryParam.projectStatus}
AND ( vendor.SIGN_UP_STATUS is null OR vendor.SIGN_UP_STATUS = #{queryParam.signUpStatus} )
AND vendor.SIGN_UP_STATUS = #{queryParam.signUpStatus}
AND sou_project.PUBLISH_SCOPE = #{queryParam.publishScope}
AND ( EXISTS( SELECT * FROM scc_sou_item sou_item where sou_item.project_id = sou_project.project_id
AND sou_item.ITEM_DESC LIKE concat('%', concat(#{queryParam.itemDesc}, '%'))
) OR sou_project.PUBLISH_SCOPE = 'INVITE_TENDER' AND EXISTS( SELECT PROJECT_ID FROM scc_sou_vendor WHERE PROJECT_ID = sou_project.PROJECT_ID AND VENDOR_ID = #{queryParam.vendorId}
AND EXISTS ( SELECT sou_item.SOU_ITEM_ID FROM scc_sou_item sou_item WHERE sou_item.PROJECT_ID = sou_project.PROJECT_ID AND sou_item.ITEM_ID = #{queryParam.itemId} )
AND EXISTS ( SELECT sou_item.SOU_ITEM_ID FROM scc_sou_item sou_item WHERE sou_item.PROJECT_ID = sou_project.PROJECT_ID AND sou_item.ITEM_DESC LIKE concat('%', concat(#{queryParam.itemDesc}, '%')) )
) )
AND ( sou_order.PROJECT_ID IS NULL OR sou_order.ORDER_STATUS = 'DRAFT' )
AND sou_order.ORDER_STATUS = #{queryParam.orderStatus}
order by sou_project.SOU_NO desc
